package net.civeira.phylax.feature.access.dcrinitialaccesstoken.application.usecase.update;

import java.time.LocalDateTime;
import java.time.ZoneId;

import org.junit.jupiter.api.Assertions;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;

import net.civeira.phylax.feature.access.dcrinitialaccesstoken.domain.DcrInitialAccessTokenChangeSet;
import net.civeira.phylax.feature.identity.tenant.domain.TenantReference;

class DcrInitialAccessTokenUpdateInputUnitTest {

  /**
   * @autogenerated UpdateInputGenerator
   */
  @Test
  @DisplayName("Test the dcr initial access token input values are kept when converted to a change set and back")
  void test_dcr_initial_access_token_update_input_change_set_round_trip() {
    DcrInitialAccessTokenUpdateInput input = DcrInitialAccessTokenUpdateInput.builder().uid("one")
        .tenant(TenantReference.of("one")).description("one")
        .expiresAt(LocalDateTime.of(1980, 8, 20, 0, 0).atZone(ZoneId.of("Europe/Madrid"))
            .toOffsetDateTime())
        .maxUses(1).uses(1).allowedGrantTypes("one").revokedAt(LocalDateTime.of(1980, 8, 20, 0, 0)
            .atZone(ZoneId.of("Europe/Madrid")).toOffsetDateTime())
        .version(1).build();
    DcrInitialAccessTokenChangeSet changes = input.toChangeSet();
    Assertions.assertNotNull(changes, "A change set must be created");
    DcrInitialAccessTokenUpdateInput copy = DcrInitialAccessTokenUpdateInput.fromChangeSet(changes);
    Assertions.assertTrue(input.getUid().isPresent(), "uid must be assigned by the builder");
    Assertions.assertEquals(input.getUid(), copy.getUid(),
        "uid must survive the change set round trip");
    Assertions.assertTrue(input.getTenant().isPresent(), "tenant must be assigned by the builder");
    Assertions.assertEquals(input.getTenant(), copy.getTenant(),
        "tenant must survive the change set round trip");
    Assertions.assertTrue(input.getDescription().isPresent(),
        "description must be assigned by the builder");
    Assertions.assertEquals(input.getDescription(), copy.getDescription(),
        "description must survive the change set round trip");
    Assertions.assertTrue(input.getExpiresAt().isPresent(),
        "expiresAt must be assigned by the builder");
    Assertions.assertEquals(input.getExpiresAt(), copy.getExpiresAt(),
        "expiresAt must survive the change set round trip");
    Assertions.assertTrue(input.getMaxUses().isPresent(),
        "maxUses must be assigned by the builder");
    Assertions.assertEquals(input.getMaxUses(), copy.getMaxUses(),
        "maxUses must survive the change set round trip");
    Assertions.assertTrue(input.getUses().isPresent(), "uses must be assigned by the builder");
    Assertions.assertEquals(input.getUses(), copy.getUses(),
        "uses must survive the change set round trip");
    Assertions.assertTrue(input.getAllowedGrantTypes().isPresent(),
        "allowedGrantTypes must be assigned by the builder");
    Assertions.assertEquals(input.getAllowedGrantTypes(), copy.getAllowedGrantTypes(),
        "allowedGrantTypes must survive the change set round trip");
    Assertions.assertTrue(input.getRevokedAt().isPresent(),
        "revokedAt must be assigned by the builder");
    Assertions.assertEquals(input.getRevokedAt(), copy.getRevokedAt(),
        "revokedAt must survive the change set round trip");
    Assertions.assertTrue(input.getVersion().isPresent(),
        "version must be assigned by the builder");
    Assertions.assertEquals(input.getVersion(), copy.getVersion(),
        "version must survive the change set round trip");
  }

  /**
   * @autogenerated UpdateInputGenerator
   */
  @Test
  @DisplayName("Test the dcr initial access token input builder can generate a new identifier")
  void test_dcr_initial_access_token_update_input_new_uid() {
    DcrInitialAccessTokenUpdateInput input =
        DcrInitialAccessTokenUpdateInput.builder().newUid().build();
    Assertions.assertTrue(input.getUid().isPresent(), "A new uid must be generated");
    Assertions.assertTrue(input.getVersion().isPresent(), "The initial version must be assigned");
    Assertions.assertNotEquals(input.getUid(),
        DcrInitialAccessTokenUpdateInput.builder().newUid().build().getUid(),
        "Each new uid must be different");
  }

  /**
   * @autogenerated UpdateInputGenerator
   */
  @Test
  @DisplayName("Test the dcr initial access token input starts empty and the setters assign values")
  void test_dcr_initial_access_token_update_input_setters() {
    DcrInitialAccessTokenUpdateInput empty = DcrInitialAccessTokenUpdateInput.builder().build();
    Assertions.assertTrue(empty.getUid().isEmpty(), "uid must be empty by default");
    Assertions.assertSame(empty, empty.setUid("one"), "The setter must allow a flow code");
    Assertions.assertTrue(empty.getUid().isPresent(), "uid must be assigned by the setter");
    Assertions.assertTrue(empty.getTenant().isEmpty(), "tenant must be empty by default");
    Assertions.assertSame(empty, empty.setTenant(TenantReference.of("one")),
        "The setter must allow a flow code");
    Assertions.assertTrue(empty.getTenant().isPresent(), "tenant must be assigned by the setter");
    Assertions.assertTrue(empty.getDescription().isEmpty(), "description must be empty by default");
    Assertions.assertSame(empty, empty.setDescription("one"), "The setter must allow a flow code");
    Assertions.assertTrue(empty.getDescription().isPresent(),
        "description must be assigned by the setter");
    Assertions.assertTrue(empty.getExpiresAt().isEmpty(), "expiresAt must be empty by default");
    Assertions.assertSame(
        empty, empty.setExpiresAt(LocalDateTime.of(1980, 8, 20, 0, 0)
            .atZone(ZoneId.of("Europe/Madrid")).toOffsetDateTime()),
        "The setter must allow a flow code");
    Assertions.assertTrue(empty.getExpiresAt().isPresent(),
        "expiresAt must be assigned by the setter");
    Assertions.assertTrue(empty.getMaxUses().isEmpty(), "maxUses must be empty by default");
    Assertions.assertSame(empty, empty.setMaxUses(1), "The setter must allow a flow code");
    Assertions.assertTrue(empty.getMaxUses().isPresent(), "maxUses must be assigned by the setter");
    Assertions.assertTrue(empty.getUses().isEmpty(), "uses must be empty by default");
    Assertions.assertSame(empty, empty.setUses(1), "The setter must allow a flow code");
    Assertions.assertTrue(empty.getUses().isPresent(), "uses must be assigned by the setter");
    Assertions.assertTrue(empty.getAllowedGrantTypes().isEmpty(),
        "allowedGrantTypes must be empty by default");
    Assertions.assertSame(empty, empty.setAllowedGrantTypes("one"),
        "The setter must allow a flow code");
    Assertions.assertTrue(empty.getAllowedGrantTypes().isPresent(),
        "allowedGrantTypes must be assigned by the setter");
    Assertions.assertTrue(empty.getRevokedAt().isEmpty(), "revokedAt must be empty by default");
    Assertions.assertSame(
        empty, empty.setRevokedAt(LocalDateTime.of(1980, 8, 20, 0, 0)
            .atZone(ZoneId.of("Europe/Madrid")).toOffsetDateTime()),
        "The setter must allow a flow code");
    Assertions.assertTrue(empty.getRevokedAt().isPresent(),
        "revokedAt must be assigned by the setter");
    Assertions.assertTrue(empty.getVersion().isEmpty(), "version must be empty by default");
    Assertions.assertSame(empty, empty.setVersion(1), "The setter must allow a flow code");
    Assertions.assertTrue(empty.getVersion().isPresent(), "version must be assigned by the setter");
    Assertions.assertNotNull(empty.toChangeSet(), "A change set must be created");
  }
}
